  1	/* ============================================================================
  2	   GATED AUTOPILOT — answers candidate replies like a person, inside hard
  3	   guardrails, or hands the message to a human. Never both, never neither.
  4	
  5	   Flow (WhatsApp first, email later):
  6	     inbound webhook → parseWhatsAppWebhook() → thread to candidate/spec →
  7	     composeReply() with an injected LLM `generate` fn → decideAutopilot():
  8	       - spec.guardrails.autopilot off        → queue for human (status blocked)
  9	       - canary_remaining > 0                 → queue for human, decrement canary
 10	       - reply commits to salary/offer/legal  → queue for human
 11	       - human-likeness gate fails            → queue for human
 12	       - otherwise                            → schedule send (human pacing)
 13	   Dispatch happens in /api/cron/dispatch-outbound, which re-runs the gate and
 14	   the atomic claim_and_record guardrail before anything touches the wire.
 15	
 16	   Pure logic lives here (injectable, deterministic, unit-tested); all DB and
 17	   HTTP side effects live in the API routes.
 18	   ========================================================================== */
 19	
 20	import { createHmac, timingSafeEqual } from "crypto";
 21	import { gateOutbound, type GateVerdict } from "./gate";
 22	import { humanizeText } from "./humanizer";
