 24	// ---------------------------------------------------------------------------
 25	// Meta webhook: signature + payload parsing
 26	// ---------------------------------------------------------------------------
 27	
 28	/** Verify Meta's X-Hub-Signature-256 header (HMAC-SHA256 of the raw body). */
 29	export function verifyMetaSignature(rawBody: string, header: string | null, appSecret: string): boolean {
 30	  if (!header || !appSecret) return false;
 31	  const expected = `sha256=${createHmac("sha256", appSecret).update(rawBody, "utf8").digest("hex")}`;
 32	  const a = Buffer.from(header);
 33	  const b = Buffer.from(expected);
 34	  return a.length === b.length && timingSafeEqual(a, b);
 35	}
