 37	export interface InboundWhatsApp {
 38	  /** Sender phone in E.164 without '+' (as Meta delivers it). */
 39	  from: string;
 40	  /** Meta phone-number ID identifies the ARIA workspace sender. */
 41	  senderPhoneNumberId: string;
 42	  /** Meta message id — dedupe key (unique per workspace+channel in DB). */
 43	  providerId: string;
 44	  text: string;
 45	  timestamp: number;
 46	}
 47	
 48	export interface WhatsAppDeliveryStatus {
 49	  /** Meta phone-number ID identifies the ARIA workspace sender. */
 50	  senderPhoneNumberId: string;
 51	  /** Meta outbound message id, used to reconcile the exact outbox row. */
 52	  providerMessageId: string;
 53	  /** Provider acceptance, delivery, read receipt, or a terminal failure. */
 54	  status: "sent" | "delivered" | "read" | "failed";
 55	  /** Provider event time in Unix milliseconds. */
 56	  occurredAt: number;
 57	  /** Numeric provider code only: never store recipient or provider prose. */
 58	  providerErrorCode?: number;
 59	}
