 61	/**
 62	 * Extract text messages from a WhatsApp Cloud API webhook payload. Ignores
 63	 * statuses (delivered/read receipts) and non-text message types.
 64	 */
 65	export function parseWhatsAppWebhook(payload: unknown): InboundWhatsApp[] {
 66	  const out: InboundWhatsApp[] = [];
 67	  const entries = (payload as { entry?: unknown[] })?.entry;
 68	  if (!Array.isArray(entries)) return out;
 69	  for (const entry of entries) {
 70	    const changes = (entry as { changes?: unknown[] })?.changes;
 71	    if (!Array.isArray(changes)) continue;
 72	    for (const change of changes) {
 73	      const value = (change as { value?: { messages?: unknown[]; metadata?: { phone_number_id?: string } } })?.value;
 74	      const messages = value?.messages;
 75	      if (!Array.isArray(messages)) continue;
 76	      const senderPhoneNumberId = value?.metadata?.phone_number_id;
 77	      if (!senderPhoneNumberId) continue;
 78	      for (const raw of messages) {
 79	        const m = raw as {
 80	          from?: string;
 81	          id?: string;
 82	          timestamp?: string;
 83	          type?: string;
 84	          text?: { body?: string };
 85	        };
 86	        if (m.type !== "text" || !m.from || !m.id || typeof m.text?.body !== "string") continue;
 87	        out.push({
 88	          from: m.from,
 89	          senderPhoneNumberId,
 90	          providerId: m.id,
 91	          text: m.text.body,
 92	          timestamp: Number(m.timestamp ?? 0) * 1000,
 93	        });
 94	      }
 95	    }
 96	  }
 97	  return out;
 98	}
