100	/**
101	 * Extract signed Meta delivery/read status receipts separately from inbound
102	 * candidate text. Receipts never enter the reply composer or message inbox;
103	 * they are append-only reconciliation facts for an already accepted outbound.
104	 */
105	export function parseWhatsAppDeliveryStatuses(payload: unknown): WhatsAppDeliveryStatus[] {
106	  const out: WhatsAppDeliveryStatus[] = [];
107	  const entries = (payload as { entry?: unknown[] })?.entry;
108	  if (!Array.isArray(entries)) return out;
109	  for (const entry of entries) {
110	    const changes = (entry as { changes?: unknown[] })?.changes;
111	    if (!Array.isArray(changes)) continue;
112	    for (const change of changes) {
113	      const value = (change as {
114	        value?: { statuses?: unknown[]; metadata?: { phone_number_id?: string } };
115	      })?.value;
116	      const senderPhoneNumberId = value?.metadata?.phone_number_id;
117	      const statuses = value?.statuses;
118	      if (!senderPhoneNumberId || !Array.isArray(statuses)) continue;
119	      for (const raw of statuses) {
120	        const status = raw as {
121	          id?: string;
122	          status?: string;
123	          timestamp?: string;
124	          errors?: Array<{ code?: unknown }>;
125	        };
126	        if (
127	          !status.id ||
128	          (status.status !== "sent" && status.status !== "delivered" && status.status !== "read" && status.status !== "failed")
129	        ) {
130	          continue;
131	        }
132	        const seconds = Number(status.timestamp);
133	        if (!Number.isFinite(seconds) || seconds <= 0) continue;
134	        const rawCode = status.errors?.[0]?.code;
135	        const providerErrorCode =
136	          typeof rawCode === "number" && Number.isFinite(rawCode)
137	            ? rawCode
138	            : typeof rawCode === "string" && /^\d{1,12}$/.test(rawCode)
139	              ? Number(rawCode)
140	              : undefined;
141	        out.push({
142	          senderPhoneNumberId,
143	          providerMessageId: status.id,
144	          status: status.status,
145	          occurredAt: Math.floor(seconds * 1_000),
146	          ...(providerErrorCode === undefined ? {} : { providerErrorCode }),
147	        });
148	      }
149	    }
150	  }
151	  return out;
152	}
