159	export interface ComposeContext {
160	  /** The candidate's inbound message. */
161	  inbound: string;
162	  /** The last message we sent them (thread context). */
163	  lastOutbound: string;
164	  /** Role brief summary (title, seniority, key facts) for factual answers. */
