189	// ---------------------------------------------------------------------------
190	// Autopilot decision — send inside guardrails, otherwise queue for the human.
191	// ---------------------------------------------------------------------------
192	
193	export interface SpecGuardrails {
194	  autopilot?: boolean;
195	  canary_remaining?: number;
196	  topics_allow?: string[];
197	  max_per_day?: number;
198	}
199	
200	/** Content a texting agent must never commit to on its own. */
201	const COMMITMENT_PATTERNS: [RegExp, string][] = [
202	  [/\b(salary|compensation|package) (is|will be|of)\b/i, "commitment-salary"],
203	  [/\b\d{2,3}[ ,.]?\d{3}\s*(€|EUR|USD|\$|CHF|GBP|£)|\b(€|\$|£)\s*\d{2,3}[ ,.]?\d{3}\b/i, "commitment-salary"],
204	  [/\b(we|I) (can|will) (offer|guarantee|promise)\b/i, "commitment-offer"],
205	  [/\byou (are|'re) hired\b/i, "commitment-offer"],
206	  [/\b(offer letter|contract|signing bonus|equity grant)\b/i, "commitment-contract"],
207	];
208	
209	export type AutopilotDecision = { action: "queue"; text: string; reasons: string[] };
210	
211	/**
212	 * Decide what happens to a composed reply. `queue` means a human (the spec
213	 * owner) reviews it in the Replies queue; `send` means it may be scheduled —
214	 * the dispatcher still re-gates and runs claim_and_record before the wire.
215	 */
216	export function decideAutopilot(replyDraft: string, guardrails: SpecGuardrails): AutopilotDecision {
217	  // Soft-clean first so the human queue receives reviewable text either way.
218	  const cleaned = humanizeText(replyDraft ?? "");
219	  // Autopilot may classify and draft, but a named operator makes the only
220	  // approval that can release an external message.
221	  const reasons: string[] = ["human-review-required"];
222	
223	  if (!guardrails.autopilot) reasons.push("autopilot-off");
224	  if ((guardrails.canary_remaining ?? 0) > 0) reasons.push("canary");
225	
226	  for (const [re, reason] of COMMITMENT_PATTERNS) {
227	    if (re.test(cleaned) && !reasons.includes(reason)) reasons.push(reason);
228	  }
229	
230	  const gate: GateVerdict = gateOutbound(cleaned);
231	  if (!gate.pass) reasons.push(...gate.reasons.map((r) => `gate:${r}`));
232	
233	  return { action: "queue", text: gate.pass ? gate.text : cleaned, reasons };
234	}

  1	/* ============================================================================
  2	   LinkedIn policy enforcement.
  3	   LinkedIn's User Agreement and Recruiter terms prohibit automated login,
  4	   scraping, and unsolicited automated messaging. This module gives the app a
  5	   single place to detect and block content or instructions that attempt to
  6	   bypass those rules.
  7	   ========================================================================== */
  8	
  9	export interface LinkedInPolicyResult {
 10	  ok: boolean;
 11	  reason?: string;
 12	  matched?: string;
 13	}
 14	
 15	const FORBIDDEN_PATTERNS = [
 16	  // Direct automation instructions
 17	  /\bautomate\s+(?:linkedin|li)\b/i,
 18	  /\blinkedin\s+(?:automation|bot|scraper|scraping|auto[-\s]?dm|mass\s*message)\b/i,
 19	  /\bscrape\s+(?:linkedin|li|profiles)\b/i,
 20	  /\blogin\s+(?:to\s+)?(?:linkedin|li)\s+(?:with\s+)?(?:credentials|account|recruiter)\b/i,
 21	  /\bsign\s*in\s+(?:to\s+)?(?:linkedin|li)\b/i,
 22	  /\bheadless\s+(?:browser|chrome|puppeteer|playwright|selenium)\b/i,
 23	  /\b(?:puppeteer|playwright|selenium).{0,40}(?:linkedin|li)\b/i,
 24	  /\bbypass\s+(?:linkedin|li)\s+(?:login|auth|captcha|rate.?limit)\b/i,
 25	  /\bscraped?\s+(?:linkedin|li)\s+(?:profiles|data|candidates)\b/i,
 26	  /\bsend\s+(?:bulk|mass|automated)\s+(?:linkedin|li)\s*(?:message|inmail|dm|invite)s?\b/i,
 27	  /\blinkedin\s+(?:recruiter)\s+(?:automation|auto[-\s]?login|scraper)\b/i,
 28	  // Tooling commonly used for unauthorized automation
 29	  /\b(?:linkedinhelper|dux-soup|octopus|meetalfred|phantombuster)\b/i,
 30	  // Fake/session evasion
 31	  /\brotate\s+(?:proxies|ips|sessions|cookies)\s+(?:linkedin|li)\b/i,
 32	  /\bfake\s+(?:linkedin|li)\s+(?:profile|identity|session|account)\b/i,
 33	];
 34	
 35	const SUSPICIOUS_PATTERNS = [
 36	  /\blinkedin\s+api\s+(?:without|unofficial|undocumented)\b/i,
 37	  /\bcrawl\s+(?:linkedin|li)\b/i,
 38	  /\bharvest\s+(?:linkedin|li)\s+(?:profiles|emails)\b/i,
 39	];
 40	
 41	export function checkLinkedInPolicy(text: string): LinkedInPolicyResult {
 42	  if (!text || typeof text !== "string") return { ok: true };
 43	  const normalized = text.toLowerCase();
 44	  for (const pattern of FORBIDDEN_PATTERNS) {
 45	    const match = normalized.match(pattern);
 46	    if (match) {
 47	      return {
 48	        ok: false,
 49	        reason: "This content attempts to automate, scrape, or bypass LinkedIn. That violates LinkedIn's terms and this platform's guardrails.",
 50	        matched: match[0],
 51	      };
 52	    }
 53	  }
 54	  for (const pattern of SUSPICIOUS_PATTERNS) {
 55	    const match = normalized.match(pattern);
 56	    if (match) {
 57	      return {
 58	        ok: false,
 59	        reason: "This content describes an unauthorized LinkedIn data-collection method.",
 60	        matched: match[0],
 61	      };
 62	    }
 63	  }
 64	  return { ok: true };
 65	}
