 72	export function getOutboundChannelPolicy(channel: string | undefined): LinkedInPolicyResult {
 73	  if (channel === "LinkedIn") {
 74	    return {
 75	      ok: false,
 76	      reason:
 77	        "LinkedIn delivery is assisted-manual only. Copy the approved draft and send it yourself, or use a separately approved official LinkedIn integration.",
 78	    };
 79	  }
 80	  return { ok: true };
 81	}
