  3	/* ============================================================================
  4	   Candidate confidentiality / data minimization.
  5	   Candidate PII is purpose-limited to outreach. When confidentiality mode is on,
  6	   contact identifiers are masked everywhere except an active outreach context,
  7	   and any reveal is written to the audit trail by the caller.
  8	   ========================================================================== */
  9	
 10	export function maskEmail(email: string): string {
 11	  if (!email || !email.includes("@")) return "•••";
 12	  const [local, domain] = email.split("@");
 13	  const tld = domain.includes(".") ? domain.slice(domain.lastIndexOf(".")) : "";
 14	  const d = domain.replace(tld, "");
 15	  return `${local[0] ?? "•"}•••@${d[0] ?? "•"}•••${tld}`;
 16	}
 17	
 18	export function maskName(name: string): string {
 19	  const parts = name.trim().split(/\s+/).filter(Boolean);
 20	  if (parts.length === 0) return "•••";
 21	  if (parts.length === 1) return `${parts[0][0]}•••`;
 22	  return `${parts[0]} ${parts[parts.length - 1][0]}.`;
 23	}
 24	
 25	/**
 26	 * Redact PII inside a free-text email/reply body for display when confidentiality
 27	 * mode is on and the operator has not revealed it. Best-effort: email addresses,
 28	 * links, and phone-like number runs become tokens. Over-redaction is acceptable
 29	 * here (privacy-first) — the operator can reveal, which is audited.
 30	 */
 31	export function maskEmailBody(text: string): string {
 32	  if (!text) return text;
 33	  return text
 34	    .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, "[email]")
 35	    .replace(/https?:\/\/[^\s)]+/g, "[link]")
 36	    .replace(/\+?\d[\d().\-\s]{6,}\d/g, "[phone]");
 37	}
 38	
 39	/**
 40	 * Return a candidate with PII masked unless revealed. `reveal` should be true
 41	 * only inside an active outreach/approval context (purpose limitation) or after
 42	 * an explicit, audited operator reveal.
 43	 */
 44	export function applyConfidentiality(
 45	  candidate: Candidate,
 46	  opts: { confidentialityMode: boolean; reveal: boolean },
 47	): Candidate {
 48	  if (!opts.confidentialityMode || opts.reveal) return candidate;
 49	  return {
 50	    ...candidate,
 51	    name: maskName(candidate.name),
 52	    email: maskEmail(candidate.email),
 53	    linkedinUrl: candidate.linkedinUrl ? "•••" : "",
 54	    githubUrl: candidate.githubUrl ? "•••" : "",
 55	    sourceUrl: candidate.sourceUrl ? "•••" : undefined,
 56	    avatarInitials: candidate.avatarInitials ? candidate.avatarInitials[0] + "•" : "•",
 57	  };
 58	}
 59	
 60	/** Whether a candidate currently has a legitimate outreach purpose to show PII. */
 61	export function hasOutreachPurpose(stage: Candidate["stage"]): boolean {
 62	  // Contacted onward implies an outreach relationship already exists.
 63	  return ["Contacted", "Replied", "Interested", "Booked", "Interviewed", "Offer", "Hired"].includes(
 64	    stage,
 65	  );
 66	}
  1	/* ============================================================================
  2	   HUMAN-LIKENESS GATE — the last wall between an agent and a candidate.
  3	
  4	   Every outbound message (Email / LinkedIn / WhatsApp / SMS) passes through
  5	   gateOutbound() before it may enter the send queue. The gate:
  6	
  7	     1. Runs humanize() (soft transforms: AI-isms → plain phrasing).
  8	     2. Hard-blocks anything that still reads as machine output — status
  9	        narration ("processing your request…"), AI self-disclosure, leaked
 10	        tool/JSON/template artifacts, placeholder text.
 11	     3. Produces the dedupe hash that messages_outbound enforces UNIQUE per
 12	        workspace, so identical text can never reach the same candidate twice.
 13	     4. Answers pacing questions (quiet hours, human-feeling send delay) so
 14	        replies never land with robotic instant timing.
 15	
 16	   Agent narration/status events NEVER pass through here — they live in
 17	   agent_events, which has no send path at all. This gate exists for the
 18	   messages that are legitimately candidate-bound.
 19	
 20	   Deterministic by design (no Math.random / Date.now inside the checks) so
 21	   every verdict is reproducible in tests and reviewable in gate_result.
 22	   ========================================================================== */
 23	
 24	import { createHash } from "crypto";
 25	import { humanize } from "./humanizer";
 26	
 27	export interface GatePass {
 28	  pass: true;
 29	  /** Final text after soft transforms — this is what may be sent. */
 30	  text: string;
 31	  /** Which soft transforms fired (from humanize). */
 32	  transformed: string[];
 33	}
 34	
 35	export interface GateBlock {
 36	  pass: false;
 37	  /** Which hard-block rules fired. Stored in messages_outbound.gate_result. */
 38	  reasons: string[];
 39	  /** Text after soft transforms, kept for the human review queue. */
 40	  text: string;
 41	}
 42	
 43	export type GateVerdict = GatePass | GateBlock;
