 45	// ---------------------------------------------------------------------------
 46	// Hard blocks — if any of these survive humanize(), the message is machine
 47	// output and must not reach a candidate. Each entry: [pattern, reason-tag].
 48	// ---------------------------------------------------------------------------
 49	const HARD_BLOCKS: [RegExp, string][] = [
 50	  // AI self-disclosure
 51	  [/\bas an? (AI|artificial intelligence|language model|LLM|virtual assistant)\b/i, "ai-disclosure"],
 52	  [/\b(I'?m|I am) (an? )?(AI|artificial intelligence|language model|LLM|bot|virtual assistant|digital assistant)\b/i, "ai-disclosure"],
 53	  [/\bAI[- ]generated\b/i, "ai-disclosure"],
 54	  [/\bmy (programming|training data|knowledge cutoff)\b/i, "ai-disclosure"],
 55	
 56	  // Status / progress narration — "an action getting done" must never be a message
 57	  [/\b(processing|analyzing|computing|calculating|generating|retrieving|fetching) (your|the|this) (request|message|reply|response|data|profile)\b/i, "status-narration"],
 58	  [/\bplease (wait|hold on|stand by) (while|as) I\b/i, "status-narration"],
 59	  [/\bone moment while I\b/i, "status-narration"],
 60	  [/^\s*(thinking|processing|calculating|analyzing|working|loading|searching|typing)\s*(\.{2,}|…)?\s*$/i, "status-narration"],
 61	  [/\b(task|action|request|operation) (has been )?(completed?|executed|performed|finished|done)\b/i, "status-narration"],
 62	  [/\bI(?:'ve| have) (now )?(completed|finished|executed|performed) (the|your|this) (task|request|action|search)\b/i, "status-narration"],
 63	  [/\bhere(?:'s| is) (the|your) (result|output|response|generated)\b/i, "status-narration"],
 64	
 65	  // Leaked structure: tool calls, JSON, markdown fences, chat-role prefixes
 66	  [/```/, "leaked-markup"],
 67	  [/^\s*[{[][\s{[]*"/, "leaked-json"],
 68	  [/<\/?(tool|function|thinking|antml|system|assistant|response)[\s>:_-]/i, "leaked-markup"],
 69	  [/^\s*(system|assistant|user)\s*:/im, "leaked-role-prefix"],
 70	
 71	  // Unfilled templates / placeholders
 72	  [/\{\{[^}]*\}\}/, "placeholder"],
 73	  [/\[(INSERT|PLACEHOLDER|NAME|CANDIDATE|COMPANY|ROLE|TODO|FIXME)[^\]]*\]/i, "placeholder"],
 74	  [/<(INSERT|NAME|CANDIDATE|COMPANY|ROLE)[^>]*>/i, "placeholder"],
 75	
 76	  // Meta about instructions / capabilities — human recruiters never say this
 77	  [/\bbased on (the|your|my) (instructions|prompt|system message)\b/i, "meta-instructions"],
 78	  [/\baccording to my (instructions|guidelines|programming)\b/i, "meta-instructions"],
 79	  [/\bI (don'?t|do not) have (access to|the ability to|real[- ]time)\b/i, "meta-instructions"],
