12	/**
13	 * Record a human approval for a SPECIFIC outbound message.
14	 *
15	 * The send route (/api/outreach/send) refuses to send a message that has no
16	 * matching approval row (by message_id + a sha256 of its exact subject+body), so
17	 * the "human approval required / never auto-send" guarantee is enforced
18	 * server-side — not just in browser state. Re-approving the same message_id with
19	 * different content updates the recorded hash (re-review required after an edit).
20	 */
21	const ApproveSchema = z.object({
22	  messageId: z.string().min(1).max(120),
23	  candidateId: z.string().min(1).max(120),
24	  channel: z.enum(["Email", "LinkedIn", "WhatsApp", "SMS"]),
25	  recipient: z.string().min(1).max(255),
26	  subject: z.string().min(1).max(255),
27	  body: z.string().min(1).max(50_000),
28	});
