30	export async function POST(req: NextRequest) {
31	  // Fail closed in production when the enforcement backend is absent.
32	  const prodBlock = prodFailClosed();
33	  if (prodBlock) return prodBlock;
34	  if (!supabaseEnabled) {
35	    return NextResponse.json({ ok: false, error: "No backend configured." }, { status: 503 });
36	  }
37	
38	  const rl = checkRateLimit(rateLimitKey(req, "outreach-approve"), { windowMs: 60_000, max: 60 });
39	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
40	
41	  const supabase = await getServerSupabase();
42	  if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
43	
44	  const {
45	    data: { user },
46	  } = await supabase.auth.getUser();
47	  if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
48	
49	  const { data: role } = await supabase.rpc("current_profile_role");
50	  if (!can(role as Role, "outreach")) {
51	    return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
52	  }
53	
54	  const validated = await validateBody(req, ApproveSchema, { maxBytes: 100_000 });
55	  if (!validated.ok) return validated.response;
56	  const { messageId, candidateId, channel, recipient, subject, body } = validated.data;
57	
58	  const { data: wid } = await supabase.rpc("current_workspace_id");
59	  if (!wid) return NextResponse.json({ ok: false, error: "Workspace not found." }, { status: 400 });
60	
61	  // Hash the EXACT content the operator approved; the send route recomputes this
62	  // and refuses if it differs (the body was changed after approval).
63	  const bodyHash = approvalHash(subject, body);
64	  const scopeHash = approvalScopeHash({ candidateId, channel, recipient });
65	  if (!scopeHash) return NextResponse.json({ ok: false, error: "Invalid approval recipient." }, { status: 400 });
66	
67	  if (publicDemoSideEffectsDisabled()) {
68	    return NextResponse.json({ ok: true, status: "dry-run", persisted: false, detail: PUBLIC_DEMO_DRY_RUN_DETAIL });
69	  }
70	
71	  const { data: recorded, error } = await supabase.rpc("record_outreach_approval", {
72	    p_message_id: messageId,
73	    p_body_hash: bodyHash,
74	    p_approval_scope_hash: scopeHash,
75	  });
76	  const result = recorded as { ok?: boolean; reason?: string } | null;
77	  if (error || result?.ok !== true) {
78	    if (result?.reason === "already-dispatching") {
79	      return NextResponse.json({ ok: false, error: "This message has already entered delivery." }, { status: 409 });
80	    }
81	    return NextResponse.json({ ok: false, error: "Failed to record approval." }, { status: 500 });
82	  }
83	  return NextResponse.json({ ok: true });
84	}

