 34	async function requireReviewer(req: NextRequest) {
 35	  const prodBlock = prodFailClosed();
 36	  if (prodBlock) return { ok: false as const, response: prodBlock };
 37	  if (!supabaseEnabled) {
 38	    return {
 39	      ok: false as const,
 40	      response: NextResponse.json({ ok: false, error: "No enforcement backend configured." }, { status: 503 }),
 41	    };
 42	  }
 43	
 44	  const supabase = await getServerSupabase();
 45	  if (!supabase) {
 46	    return {
 47	      ok: false as const,
 48	      response: NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 503 }),
 49	    };
 50	  }
 51	  const {
 52	    data: { user },
 53	  } = await supabase.auth.getUser();
 54	  if (!user) {
 55	    return {
 56	      ok: false as const,
 57	      response: NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 }),
 58	    };
 59	  }
 60	  const { data: role } = await supabase.rpc("current_profile_role");
 61	  if (!can(role as Role, "outreach")) {
 62	    return {
 63	      ok: false as const,
 64	      response: NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 }),
