 70	/** Human-review inbox for server-persisted WhatsApp reply drafts. */
 71	export async function GET(req: NextRequest) {
 72	  const reviewer = await requireReviewer(req);
 73	  if (!reviewer.ok) return reviewer.response;
 74	
 75	  const rl = checkRateLimit(rateLimitKey(req, "whatsapp-review-read", reviewer.userId), { windowMs: 60_000, max: 120 });
 76	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
 77	
 78	  const { data, error } = await reviewer.supabase
 79	    .from("messages_outbound")
 80	    .select("id, candidate_id, to_address, subject, body, type, channel, status, gate_result, created_at, review_decision")
 81	    .eq("channel", "WhatsApp")
 82	    .eq("status", "blocked")
 83	    .is("review_decision", null)
 84	    .order("created_at", { ascending: true })
 85	    .limit(50);
 86	  if (error) {
 87	    return NextResponse.json({ ok: false, error: "Could not load WhatsApp review drafts." }, { status: 500 });
 88	  }
 89	
 90	  const drafts = ((data ?? []) as ReviewRow[]).filter((row) =>
 91	    isReviewableWhatsAppDraft({
 92	      channel: row.channel,
 93	      status: row.status,
 94	      type: row.type,
 95	      reviewDecision: row.review_decision,
 96	    }),
 97	  );
 98	  return NextResponse.json({ ok: true, drafts });
 99	}
