101	/** Record a named human decision. The SQL RPC locks and atomically queues only
102	 * the exact stored message that was reviewed. */
103	export async function POST(req: NextRequest) {
104	  const reviewer = await requireReviewer(req);
105	  if (!reviewer.ok) return reviewer.response;
106	
107	  const rl = checkRateLimit(rateLimitKey(req, "whatsapp-review-write", reviewer.userId), { windowMs: 60_000, max: 60 });
108	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
109	
110	  const validated = await validateBody(req, ReviewSchema, { maxBytes: 2_000 });
111	  if (!validated.ok) return validated.response;
112	  const { messageId, action } = validated.data;
113	
114	  const { data: current, error: currentErr } = await reviewer.supabase
115	    .from("messages_outbound")
116	    .select("id, channel, status, type, body, review_decision")
117	    .eq("id", messageId)
118	    .maybeSingle();
119	  if (currentErr) {
120	    return NextResponse.json({ ok: false, error: "Could not load the WhatsApp draft." }, { status: 500 });
121	  }
122	  if (!current || !isReviewableWhatsAppDraft({
123	    channel: current.channel,
124	    status: current.status,
125	    type: current.type,
126	    reviewDecision: current.review_decision,
127	  })) {
128	    return NextResponse.json({ ok: false, error: "This WhatsApp draft is no longer awaiting review." }, { status: 409 });
129	  }
130	
131	  if (action === "approve") {
132	    const gate = gateOutbound(current.body);
133	    if (!gate.pass) {
134	      return NextResponse.json(
135	        { ok: false, error: "This draft still fails the candidate-message safety gate." },
136	        { status: 422 },
137	      );
138	    }
139	  }
140	
141	  if (publicDemoSideEffectsDisabled()) {
142	    return NextResponse.json({ ok: true, status: "dry-run", persisted: false, detail: PUBLIC_DEMO_DRY_RUN_DETAIL });
143	  }
144	
145	  const { data, error } = await reviewer.supabase.rpc("review_whatsapp_outbound", {
146	    p_message_id: messageId,
147	    p_decision: action,
148	  });
149	  const result = data as { ok?: boolean; reason?: string; status?: string } | null;
150	  if (error || result?.ok !== true) {
151	    const status = result?.reason === "already-dispatching" || result?.reason === "not-reviewable" ? 409 : 500;
152	    return NextResponse.json({ ok: false, error: "Could not record the WhatsApp review decision." }, { status });
153	  }
154	  return NextResponse.json({ ok: true, status: result.status ?? (action === "approve" ? "queued" : "rejected") });
155	}

  1	/* ============================================================================
  2	   OUTBOUND DISPATCHER — the ONLY path from messages_outbound to the wire.
  3	
  4	   Every queued message that is due must clear, in order:
  5	     1. an approval row for exactly this message id + body hash (autopilot
  6	        writes one when scheduling; a human click writes one in the Replies UI),
  7	     2. the human-likeness gate — again, defence in depth,
  8	     3. a live seat of the right provider,
  9	     4. claim_whatsapp_outbound for WhatsApp, which atomically validates
 10	        consent, DNC, template/window, seat, and the delivery ledger.
 11	        SMS uses the existing claim_and_record path.
 12	   Anything that fails flips to 'blocked' (human queue) or 'failed'; an
 13	   unconfigured provider is counted separately. A message never silently retries
 14	   into a double-send (dedupe_hash UNIQUE + ledger claim).
 15	
 16	   Called from two places (Vercel Hobby forbids minute crons):
 17	     - /api/webhooks/whatsapp — opportunistic drain after each inbound event
 18	       (delivery/read receipts arrive constantly, so due messages go out with
 19	       near-human latency),
 20	     - /api/cron/dispatch-outbound — daily backstop for quiet periods.
 21	   ========================================================================== */
