 42	export interface DispatchStats {
 43	  processed: number;
 44	  sent: number;
 45	  blocked: number;
 46	  failed: number;
 47	  unconfigured: number;
 48	}
 49	
 50	type DispatchOutcomeCounter = Exclude<keyof DispatchStats, "processed">;
 51	
 52	async function cacheWhatsAppGateVerdict(
 53	  supabase: SupabaseClient,
 54	  workspaceId: string,
 55	  body: string,
 56	  gate: ReturnType<typeof gateOutbound>,
 57	): Promise<boolean> {
 58	  const contentHash = createHash("sha256").update(body, "utf8").digest("hex");
 59	  const now = new Date();
 60	  const { error } = await supabase.from("outbound_content_cache").upsert(
 61	    {
 62	      workspace_id: workspaceId,
 63	      content_hash: contentHash,
 64	      gate_version: WHATSAPP_GATE_CACHE_VERSION,
 65	      verdict: gate.pass ? "pass" : "block",
 66	      reasons: gate.pass ? [] : gate.reasons,
 67	      observed_at: now.toISOString(),
 68	      expires_at: new Date(now.getTime() + WHATSAPP_GATE_CACHE_TTL_MS).toISOString(),
 69	    },
 70	    { onConflict: "workspace_id,content_hash,gate_version" },
 71	  );
 72	  if (!error) return true;
 73	  safeLog("dispatch-outbound: WhatsApp content-gate cache error", { message: error.message });
 74	  return false;
 75	}
