 77	export async function dispatchDue(supabase: SupabaseClient, limit = 10, messageId?: string): Promise<DispatchStats> {
 78	  const stats: DispatchStats = { processed: 0, sent: 0, blocked: 0, failed: 0, unconfigured: 0 };
 79	
 80	  // A public demo may still use a real Supabase database. Never let a queued
 81	  // row from that shared environment reach a provider, regardless of caller.
 82	  if (publicDemoSideEffectsDisabled()) return stats;
 83	
 84	  let dueQuery = supabase
 85	    .from("messages_outbound")
 86	    .select("id, workspace_id, spec_id, candidate_id, seat_id, channel, to_address, subject, body, type, template_id, template_parameters, approval_message_id, review_decision")
 87	    .eq("status", "queued")
 88	    .lte("scheduled_at", new Date().toISOString());
 89	  if (messageId) dueQuery = dueQuery.eq("id", messageId);
 90	  const { data: due, error: dueErr } = await dueQuery
 91	    .order("scheduled_at", { ascending: true })
 92	    .limit(limit);
 93	  if (dueErr) {
 94	    safeLog("dispatch-outbound: select error", { message: dueErr.message });
 95	    return stats;
 96	  }
 97	
 98	  for (const msg of due ?? []) {
 99	    stats.processed++;
100	    let deliveryAttemptId: string | null = null;
101	    const finish = async (status: "sent" | "blocked" | "failed", gateResult?: unknown, countAs?: DispatchOutcomeCounter) => {
102	      const reopenReview =
103	        status === "blocked" &&
104	        shouldReopenWhatsAppReview({
105	          channel: msg.channel,
106	          type: msg.type,
107	          status,
108	          reviewDecision: msg.review_decision ?? null,
109	        });
110	      let transition = supabase
111	        .from("messages_outbound")
112	        .update({
113	          status,
114	          ...(status === "sent" ? { sent_at: new Date().toISOString() } : {}),
115	          ...(gateResult !== undefined ? { gate_result: gateResult } : {}),
116	          ...(reopenReview ? { review_decision: null, reviewed_at: null, reviewed_by: null } : {}),
117	        })
118	        .eq("id", msg.id)
119	        .eq("status", deliveryAttemptId ? "dispatching" : "queued");
120	      if (deliveryAttemptId) {
121	        transition = transition.eq("delivery_attempt_id", deliveryAttemptId);
122	      }
123	      const { data: transitioned, error: transitionError } = await transition
124	        .select("id")
125	        .maybeSingle();
126	      if (transitionError) {
127	        safeLog("dispatch-outbound: terminal transition error", { message: transitionError.message });
128	        return;
129	      }
130	      if (transitioned) stats[countAs ?? status]++;
131	    };
132	
133	    try {
134	      // SMS has no equivalent consent, opt-out, suppression, or durable-outbox
135	      // policy yet. Never let a service-role row turn into a live Twilio send.
136	      if (msg.channel === "SMS") {
137	        await finish("blocked", { pass: false, reasons: ["sms-disabled-pending-consent-policy"] });
138	        continue;
139	      }
140	
141	      // A Meta-approved template is not free-form candidate copy. Before
142	      // looking up its approval, reconstruct the exact audit payload from the
143	      // current trusted template record and normalized stored parameters. This
144	      // makes a post-approval change to template identity, locale, sender,
145	      // version, schema, or parameters fail closed before the DB claim.
146	      const isApprovedWhatsAppTemplate = msg.channel === "WhatsApp" && msg.type === "approved_template";
147	      let whatsappTemplate: { name: string; language: string; bodyParameters: string[] } | null = null;
148	      let templateAuditBody: string | null = null;
149	      if (isApprovedWhatsAppTemplate) {
150	        const { data: template, error: templateErr } = await supabase
151	          .from("whatsapp_templates")
152	          .select("id, sender_id, meta_name, language, version, status, parameter_schema, body_parameter_count")
