173	                senderId: String(template.sender_id),
174	                metaName: String(template.meta_name),
175	                language: String(template.language),
176	                version: Number(template.version),
177	              },
178	              parameterSchema,
179	              parameters: msg.template_parameters,
180	            })
181	          : null;
182	        if (!audit) {
