184	          continue;
185	        }
186	        if (msg.subject !== APPROVED_WHATSAPP_TEMPLATE_AUDIT_SUBJECT || msg.body !== audit.body) {
187	          await finish("blocked", { pass: false, reasons: ["whatsapp:template-audit-mismatch"] });
188	          continue;
189	        }
190	        templateAuditBody = audit.body;
191	        whatsappTemplate = {
192	          name: String(template.meta_name),
193	          language: String(template.language),
194	          bodyParameters: audit.parameters,
195	        };
196	      }
197	
198	      // 1. Approval must exist for exactly this message. For an externally
199	      // approved template, the canonical audit payload replaces candidate
200	      // prose so identity and normalized parameters are part of the hash.
201	      const bodyHash = isApprovedWhatsAppTemplate
202	        ? approvalHash(APPROVED_WHATSAPP_TEMPLATE_AUDIT_SUBJECT, templateAuditBody ?? "")
