204	      const approvalMessageId = msg.approval_message_id ?? msg.id;
205	      const { data: approval } = await supabase
206	        .from("outreach_approvals")
207	        .select("body_hash, approval_source, revoked_at")
208	        .eq("workspace_id", msg.workspace_id)
209	        .eq("message_id", approvalMessageId)
210	        .maybeSingle();
211	      if (!approval || approval.revoked_at || approval.body_hash !== bodyHash || approval.approval_source !== "human") {
