220	        continue;
221	      }
222	
223	      // 2. Human-likeness is a free-form text safeguard. It intentionally does
224	      // not evaluate the machine-readable audit record for an externally
225	      // approved Meta template; that record was already bound to the approval
226	      // above and the actual recipient-facing text stays in Meta's template.
